import itertools

# 4x4 Sudoku with block size 2
# indices 0..15, row i, col j => idx = i*4 + j
# constraints: each row, col, block has 1..4 exactly once.
# partial assignment:
fixed = {
    7: 2,   # row1 col3
    9: 1,   # row2 col1
    12: 4,  # row3 col0
}

rows = [list(range(i*4, (i+1)*4)) for i in range(4)]
cols = [list(range(j, 16, 4)) for j in range(4)]
blocks = []
for bi in range(2):
    for bj in range(2):
        block = []
        for i in range(2):
            for j in range(2):
                block.append((bi*2 + i)*4 + (bj*2 + j))
        blocks.append(block)

# Let's do simple backtracking
grid = [0]*16
for idx, val in fixed.items():
    grid[idx] = val

def valid(grid, idx, val):
    r, c = divmod(idx, 4)
    # check row
    for cc in range(4):
        other = r*4 + cc
        if other != idx and grid[other] == val:
            return False
    # check col
    for rr in range(4):
        other = rr*4 + c
        if other != idx and grid[other] == val:
            return False
    # check block
    br, bc = r//2, c//2
    for i in range(2):
        for j in range(2):
            other = (br*2 + i)*4 + (bc*2 + j)
            if other != idx and grid[other] == val:
                return False
    return True

def solve(grid):
    # find next empty
    try:
        idx = grid.index(0)
    except ValueError:
        return True
    for val in range(1,5):
        if valid(grid, idx, val):
            grid[idx] = val
            if solve(grid):
                return True
            grid[idx] = 0
    return False

solve(grid)
print(grid)
